const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 5a3 3 0 0 1 0 6m2 10v-3a6 6 0 0 0-3-5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18m-13 4h2m4 0h2m-8 3h2"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m7 10 5 5 5-5"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',settings:'<path d="m9 3-1 3-3 1 1 4-2 2 2 3h3l2 4h3l2-4h3l2-3-2-2 1-4-3-1-1-3Z"/><circle cx="12" cy="12" r="3"/>',chart:'<path d="M4 3v18h17M8 16v-5m5 5V7m5 9v-7"/>',building:'<path d="M3 21h18M5 21V7l7-4 7 4v14M9 9h1m4 0h1m-6 4h1m4 0h1m-6 4h1m4 0h1"/>',link:'<path d="m10 13 4-4M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2 0 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12l9 4 9-4"/>',phone:'<path d="M7 3H3c0 10 8 18 18 18v-4l-5-2-2 2-7-7 2-2Z"/>',message:'<path d="M21 15a3 3 0 0 1-3 3H8l-5 3V5a3 3 0 0 1 3-3h12a3 3 0 0 1 3 3Z"/><path d="M7 8h10M7 12h6"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',shield:'<path d="m12 3 9 4c0 8-3 11-9 14C6 18 3 15 3 7Z"/><path d="m8 12 3 3 5-6"/>',logout:'<path d="M9 3H3v18h6M9 12h12m-4-4 4 4-4 4"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',folder:'<path d="M3 7V4h7l3 3h8v14H3Z"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 3H3v18h18v-7"/>'};
const ic=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.home}</svg>`;
const uid=()=>crypto.randomUUID();
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Ho_Chi_Minh'});
const at=(offset,h=9,m=0)=>{const d=new Date();d.setDate(d.getDate()+offset);d.setHours(h,m,0,0);return d.toISOString()};
const fmtDate=d=>d?new Date(d).toLocaleDateString('vi-VN',{day:'2-digit',month:'2-digit',timeZone:'Asia/Ho_Chi_Minh'}):'Chưa có';
const fmtTime=d=>new Date(d).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Ho_Chi_Minh'});
const relative=d=>{if(!d)return 'Chưa chăm sóc';const n=Math.floor((Date.now()-new Date(d))/86400000);return n===0?'Hôm nay':n===1?'Hôm qua':n>1?`${n} ngày trước`:fmtDate(d)};
const dateKey=d=>new Date(d).toLocaleDateString('en-CA',{timeZone:'Asia/Ho_Chi_Minh'});
const money=n=>n?`${Number(n).toLocaleString('vi-VN')} tỷ`:'Chưa xác định';
const badge=(text,color='gray')=>`<span class="badge ${color}"><i class="pill-dot"></i>${esc(text)}</span>`;
const initials=n=>n.trim().split(/\s+/).slice(-2).map(x=>x[0]).join('');
const levels={high:['Quan tâm cao','red'],medium:['Đang cân nhắc','orange'],low:['Nuôi dưỡng','green'],unknown:['Chưa xác định','gray']};
const stages={new:'Khách mới',consulting:'Đang tư vấn',viewing:'Hẹn xem nhà',negotiating:'Đàm phán',won:'Đã giao dịch',lost:'Tạm dừng'};
const navs=[['dashboard','home','Tổng quan'],['customers','users','Khách hàng'],['tasks','check','Chăm sóc khách hàng'],['calendar','calendar','Lịch hẹn'],['pipeline','briefcase','Cơ hội giao dịch'],['reports','chart','Báo cáo']];
let demo=false, session=null, data={customers:[],tasks:[],activities:[],members:[],connections:[],channels:[]},route=location.hash.slice(1)||'dashboard',taskFilter='today',search='',levelFilter='',sourceFilter='',workspaceId='',tenants=[];
